contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take receiver and amount as inputs. This function is payable so the test
    // contract may hold Ether if needed, but we don't send Ether to c here.
    function run(address receiver, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // Observe balance of c before the call
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        // Call sendTo from this contract (which is the owner because it deployed C)
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule:
        // If the call reverted, then neither C's nor this contract's balances changed.
        // If the call did not revert, then C's balance decreased by exactly amount
        // and this contract's balance increased by exactly amount only if the transfer
        // sent Ether to this contract (i.e., receiver == address(this)); otherwise
        // this contract's balance is unchanged.
        assert(
            reverted
            ? (afterC == beforeC && afterThis == beforeThis)
            : (
                afterC + amount == beforeC &&
                // if receiver is this contract, it should have been credited amount;
                // otherwise this contract's balance should be unchanged by the transfer
                ((receiver == address(this) && afterThis == beforeThis + amount) || (receiver != address(this) && afterThis == beforeThis))
              )
        );
    }

    receive() external payable { }
}

